files.content:
.hero {
  container-type: inline-size;
  position: relative;
  display: grid;
  align-content: center;
  inline-size: 100%;
  min-block-size: 60dvb;
  border: 2px solid #000;
  padding: var(--internal-padding, 40px 20px);
  color: var(--hero-text-color, #fff);
  background-color: var(--hero-bg-color, #ffc802);
  background-image: var(--hero-bg-image-url, url(../../../images/hero-bg.jpg));
  background-position: center;
  background-size: cover;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background-color: rgb(0 0 0 / 0.5);
}

.hero * {
  z-index: 0;
}

.hero__title {
  max-inline-size: 800px;
  margin-block-end: 0.2em;
  font-size: 54px;
  text-transform: uppercase;
}

.hero__text {
  max-inline-size: 1000px;
  margin-block-end: 1em;
}

.hero__button {
  inline-size: fit-content;
  border: 2px solid currentColor;
  padding: 0.5em 2em;
  font-weight: bold;
  text-transform: uppercase;
  background-color: transparent;
  cursor: pointer;
}

.hero__button:hover {
  opacity: 0.6;
}
@container (width <= 600px) {
  .hero__title { font-size: 45px; }
}
